@IsTest
private class AddressVerificationServiceTest {

    private class MockCallout implements HttpCalloutMock {
        public HttpResponse response;
        public HttpRequest request;
        public Integer callCount = 0;

        public HttpResponse respond(HttpRequest req) {
            request = req;
            callCount++;
            return response;
        }
    }

    private static MockCallout mockCallout(Integer statusCode, String body) {
        MockCallout mock = new MockCallout();
        HttpResponse res = new HttpResponse();
        res.setStatusCode(statusCode);
        res.setBody(body);
        mock.response = res;
        return mock;
    }

    private static Account newAccount() {
        return new Account(
            Name = 'Test Account',
            BillingStreet = '1 Old Street',
            BillingCity = 'Old City',
            BillingPostalCode = '00000',
            BillingCountry = 'Old Country'
        );
    }

    @IsTest
    static void blankBillingStreetIsSkippedWithoutCallout() {
        MockCallout mock = mockCallout(
            200,
            '{"status":"CORRECTED","address":{"street":"1 New Street","city":"New City","postalCode":"99999","country":"New Country"}}'
        );
        Test.setMock(HttpCalloutMock.class, mock);

        Account whitespace = newAccount();
        whitespace.BillingStreet = '   ';
        AddressVerificationService.Result whitespaceResult = AddressVerificationService.verify(whitespace);
        System.assertEquals('SKIPPED', whitespaceResult.status);
        System.assertEquals(false, whitespaceResult.changed);
        System.assertEquals(0, mock.callCount, 'Whitespace BillingStreet must not make a callout.');

        Account nullStreet = newAccount();
        nullStreet.BillingStreet = null;
        AddressVerificationService.Result nullResult = AddressVerificationService.verify(nullStreet);
        System.assertEquals('SKIPPED', nullResult.status);
        System.assertEquals(false, nullResult.changed);
        System.assertEquals(0, mock.callCount, 'Null BillingStreet must not make a callout.');
    }

    @IsTest
    static void requestMatchesApiContract() {
        Account acct = new Account(
            Name = 'Request Account',
            BillingStreet = '123 Main St',
            BillingCity = 'Springfield',
            BillingPostalCode = '12345',
            BillingCountry = 'USA'
