@IsTest
private class ShippingCostCalculatorTest {

    private static void assertQuote(Decimal expected, Decimal weightKg, String zone, Boolean express, Decimal orderValue) {
        Decimal actual = ShippingCostCalculator.quote(weightKg, zone, express, orderValue);
        String msg = 'Expected ' + String.valueOf(expected) + ' but got ' + String.valueOf(actual)
            + ' for weight=' + String.valueOf(weightKg)
            + ', zone=' + String.valueOf(zone)
            + ', express=' + String.valueOf(express)
            + ', orderValue=' + String.valueOf(orderValue);
        System.assertNotEquals(null, actual, msg);
        if (expected == 0) {
            System.assertEquals(0.0, actual.doubleValue(), msg);
        } else {
            System.assertEquals(expected.stripTrailingZeros(), actual.stripTrailingZeros(), msg);
        }
    }

    private static void assertWeightException(Decimal weightKg) {
        try {
            ShippingCostCalculator.quote(weightKg, 'DOMESTIC', false, null);
            System.assert(false, 'Expected ShippingException for weight ' + String.valueOf(weightKg));
        } catch (ShippingCostCalculator.ShippingException e) {
            // expected
        }
    }

