@isTest
private class OpportunityWonHandlerTest {
    private static final String WON = 'Closed Won';
    private static final String HANDOVER = 'Handover to Customer Success';
    private static final String KICKOFF = 'Customer kick-off';

    private static Account makeAccount(String name, String rating) {
        Account a = new Account(Name = name, Rating = rating);
        insert a;
        return a;
    }

    private static Opportunity makeOpp(String name, String stage, Date closeDate, Id accountId) {
        return new Opportunity(
            Name = name,
            StageName = stage,
            CloseDate = closeDate,
            AccountId = accountId
        );
    }

    private static Set<Id> idsOf(List<Opportunity> opps) {
        Set<Id> ids = new Set<Id>();
        for (Opportunity o : opps) {
            ids.add(o.Id);
        }
        return ids;
    }

    private static User makeOtherUser() {
        String uname = 'testowner'
            + String.valueOf(DateTime.now().getTime())
            + String.valueOf(Math.abs(Crypto.getRandomInteger()))
            + String.valueOf(UserInfo.getUserId())
            + '@example.com';

        User u = new User(
            FirstName = 'Test',
            LastName = 'Owner',
            Email = uname,
            Username = uname,
            Alias = 'towner',
            TimeZoneSidKey = 'America/Los_Angeles',
            LocaleSidKey = 'en_US',
            EmailEncodingKey = 'UTF-8',
            LanguageLocaleKey = 'en_US',
            ProfileId = UserInfo.getProfileId(),
            IsActive = true
        );
        insert u;
        return u;
    }

    @isTest
    static void insertWonSetsNextStepCreatesTaskAndRatesAccount() {
        Account a = makeAccount('Insert Won Account', 'Warm');
        Date closeDate = Date.today().addDays(10);
        Opportunity o = makeOpp('Insert Won Opp', WON, closeDate, a.Id);
        o.NextStep = 'Initial';

        Test.startTest();
        insert o;
        Test.stopTest();

        Opportunity saved = [SELECT Id, NextStep, OwnerId, AccountId FROM Opportunity WHERE Id = :o.Id];
        System.assertEquals(HANDOVER, saved.NextStep, 'NextStep should be overwritten for a newly won insert');

        List<Task> tasks = [SELECT Subject, WhatId, OwnerId, ActivityDate, Priority FROM Task WHERE WhatId = :o.Id];
        System.assertEquals(1, tasks.size(), 'Exactly one task should be created');
        Task t = tasks[0];
        System.assertEquals(KICKOFF, t.Subject, 'Task subject');
        System.assertEquals(o.Id, t.WhatId, 'Task WhatId');
        System.assertEquals(saved.OwnerId, t.OwnerId, 'Task owner');
        System.assertEquals(closeDate.addDays(7), t.ActivityDate, 'Task activity date');
        System.assertEquals('High', t.Priority, 'Task priority');

        Account updated = [SELECT Rating FROM Account WHERE Id = :a.Id];
        System.assertEquals('Hot', updated.Rating, 'Account rating');
    }

    @isTest
    static void taskOwnerIsOpportunityOwner() {
        User other = makeOtherUser();
        Account a = makeAccount('Owner Account', 'Warm');
        Opportunity o = makeOpp('Owner Opp', WON, Date.today().addDays(2), a.Id);
        o.OwnerId = other.Id;

        Test.startTest();
        insert o;
        Test.stopTest();

        List<Task> tasks = [SELECT OwnerId FROM Task WHERE WhatId = :o.Id];
        System.assertEquals(1, tasks.size(), 'Expected one task');
        System.assertEquals(other.Id, tasks[0].OwnerId, 'Task owner must be the opportunity owner');
    }

    @isTest
    static void insertNonWonChangesNothing() {
        Account a = makeAccount('Non Won Insert Account', 'Warm');
        Opportunity o = makeOpp('Non Won Insert Opp', 'Prospecting', Date.today().addDays(5), a.Id);

        Test.startTest();
        insert o;
        Test.stopTest();

        Opportunity saved = [SELECT NextStep FROM Opportunity WHERE Id = :o.Id];
        System.assertEquals(null, saved.NextStep, 'NextStep must not be set for non-won insert');
        System.assertEquals(0, [SELECT COUNT() FROM Task WHERE WhatId = :o.Id], 'No task for non-won insert');
        System.assertEquals('Warm', [SELECT Rating FROM Account WHERE Id = :a.Id].Rating, 'Account rating must not change');
    }

    @isTest
    static void updateToWonSetsNextStepCreatesTaskAndRatesAccount() {
        Account a = makeAccount('Update Won Account', 'Warm');
        Date closeDate = Date.today().addDays(4);
        Opportunity o = makeOpp('Update Won Opp', 'Prospecting', closeDate, a.Id);
        insert o;
        System.assertEquals(0, [SELECT COUNT() FROM Task WHERE WhatId = :o.Id], 'Setup should not create a task');

        o.StageName = WON;
        o.NextStep = 'Initial';
        Test.startTest();
        update o;
        Test.stopTest();

        Opportunity saved = [SELECT NextStep, OwnerId FROM Opportunity WHERE Id = :o.Id];
        System.assertEquals(HANDOVER, saved.NextStep, 'NextStep should be overwritten when newly won');

        List<Task> tasks = [SELECT Subject, WhatId, OwnerId, ActivityDate, Priority FROM Task WHERE WhatId = :o.Id];
        System.assertEquals(1, tasks.size(), 'Exactly one task should be created');
        Task t = tasks[0];
        System.assertEquals(KICKOFF, t.Subject, 'Task subject');
        System.assertEquals(o.Id, t.WhatId, 'Task WhatId');
        System.assertEquals(saved.OwnerId, t.OwnerId, 'Task owner');
        System.assertEquals(closeDate.addDays(7), t.ActivityDate, 'Task activity date');
        System.assertEquals('High', t.Priority, 'Task priority');

        System.assertEquals('Hot', [SELECT Rating FROM Account WHERE Id = :a.Id].Rating, 'Account rating');
    }

    @isTest
    static void updateNonWonChangesNothing() {
        Account a = makeAccount('Non Won Update Account', 'Warm');
        Opportunity o = makeOpp('Non Won Update Opp', 'Prospecting', Date.today().addDays(6), a.Id);
        insert o;

        Test.startTest();
        o.Name = 'Non Won Update Opp Changed';
        update o;
        Test.stopTest();

