/**
 * Pure unit tests for InvoicingService.invoiceWonOpportunities().
 *
 * No DML, no SOQL and no callouts are performed:
 *  - the billing gateway is mocked (ApexMocks where the interaction is a plain return value,
 *    an explicit stub where the double has to throw - ApexMocks can only stub methods that
 *    return a value, so throwing behaviour for void/exception cases is hand rolled),
 *  - the selector is mocked through Application.Selector.setMock,
 *  - the unit of work is mocked through Application.UnitOfWork.setMock,
 *  - all record ids come from fflib_IDGenerator.
 */
@IsTest
private class InvoicingServiceTest {

    private static final String CLOSED_WON = 'Closed Won';

    private static fflib_ApexMocks mocks;
    private static IOpportunitiesSelector selectorMock;
    private static fflib_ISObjectUnitOfWork uowMock;

    // ------------------------------------------------------------------ helpers

    private static void initMocks() {
        mocks = new fflib_ApexMocks();

        selectorMock = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        // SelectorFactory.setMock() registers the mock against getSObjectType(), so it must be stubbed.
        mocks.when(selectorMock.getSObjectType()).thenReturn(Opportunity.SObjectType);
        Application.Selector.setMock(selectorMock);

        uowMock = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);
        Application.UnitOfWork.setMock(uowMock);
    }

    private static IBillingGateway mockBillingGateway() {
        IBillingGateway gatewayMock = (IBillingGateway) mocks.mock(IBillingGateway.class);
        Application.Service.setMock(IBillingGateway.class, gatewayMock);
        return gatewayMock;
    }

    private static Opportunity opportunity(Id accountId, String stageName, Decimal amount) {
        return new Opportunity(
            Id = fflib_IDGenerator.generate(Opportunity.SObjectType),
            AccountId = accountId,
            Name = 'Test Opportunity',
            StageName = stageName,
            Amount = amount
        );
    }

    // ------------------------------------------------------------------ tests

    @IsTest
    static void invoicesOnlyClosedWonOpportunitiesWithPositiveAmount() {
        initMocks();
        IBillingGateway gatewayMock = mockBillingGateway();

        Id accountOne = fflib_IDGenerator.generate(Account.SObjectType);
        Id accountTwo = fflib_IDGenerator.generate(Account.SObjectType);
        Id accountThree = fflib_IDGenerator.generate(Account.SObjectType);

        Opportunity wonOne = opportunity(accountOne, CLOSED_WON, 100.00);
        Opportunity wonTwo = opportunity(accountTwo, CLOSED_WON, 250.50);
        Opportunity stillOpen = opportunity(accountThree, 'Prospecting', 500.00);
        Opportunity zeroAmount = opportunity(accountThree, CLOSED_WON, 0);
        Opportunity nullAmount = opportunity(accountThree, CLOSED_WON, null);

        Set<Id> opportunityIds = new Set<Id>{
            wonOne.Id, wonTwo.Id, stillOpen.Id, zeroAmount.Id, nullAmount.Id
        };

        mocks.when(selectorMock.selectById(opportunityIds))
            .thenReturn(new List<Opportunity>{ wonOne, wonTwo, stillOpen, zeroAmount, nullAmount });
        mocks.when(gatewayMock.createInvoice(accountOne, wonOne.Amount)).thenReturn('INV-001');
        mocks.when(gatewayMock.createInvoice(accountTwo, wonTwo.Amount)).thenReturn('INV-002');

        Integer invoiced;

        Test.startTest();
        invoiced = InvoicingService.invoiceWonOpportunities(opportunityIds);
        Test.stopTest();

        System.assertEquals(2, invoiced, 'Only the two qualifying opportunities should be invoiced');

        System.assertEquals('Invoiced: INV-001', wonOne.NextStep, 'NextStep must carry the invoice number');
        System.assertEquals('Invoiced: INV-002', wonTwo.NextStep, 'NextStep must carry the invoice number');
        System.assertEquals(null, stillOpen.NextStep, 'Open opportunities must not be touched');
        System.assertEquals(null, zeroAmount.NextStep, 'Zero amount opportunities must not be touched');
        System.assertEquals(null, nullAmount.NextStep, 'Null amount opportunities must not be touched');

        // gateway: authenticate() first, then exactly one invoice per qualifying opportunity
        ((IBillingGateway) mocks.verify(gatewayMock, 1)).authenticate();
        ((IBillingGateway) mocks.verify(gatewayMock, 1)).createInvoice(accountOne, wonOne.Amount);
        ((IBillingGateway) mocks.verify(gatewayMock, 1)).createInvoice(accountTwo, wonTwo.Amount);

        // non qualifying opportunities are neither invoiced ...
        ((IBillingGateway) mocks.verify(gatewayMock, 0)).createInvoice(accountThree, stillOpen.Amount);

        // ... nor registered
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).registerDirty(stillOpen);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).registerDirty(zeroAmount);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).registerDirty(nullAmount);

        // ... and every invoiced opportunity is registered and committed once
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).registerDirty(wonOne);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).registerDirty(wonTwo);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).commitWork();
    }

    @IsTest
    static void authenticationFailureThrowsInvoicingExceptionAndDoesNothingElse() {
        initMocks();

        Set<Id> opportunityIds = new Set<Id>{ fflib_IDGenerator.generate(Opportunity.SObjectType) };

        BillingGatewayStub gateway = new BillingGatewayStub()
            .withAuthenticationFailure('Authentication failed: Unauthorized');
        Application.Service.setMock(IBillingGateway.class, gateway);

        InvoicingService.InvoicingException caughtException = null;

        Test.startTest();
        try {
            InvoicingService.invoiceWonOpportunities(opportunityIds);
            System.assert(false, 'An InvoicingService.InvoicingException was expected');
        } catch (InvoicingService.InvoicingException e) {
            caughtException = e;
        }
        Test.stopTest();

        System.assertNotEquals(null, caughtException, 'An InvoicingService.InvoicingException was expected');
        System.assert(
            caughtException.getMessage().contains('Authentication failed: Unauthorized'),
            'The InvoicingException must surface the gateway message but was: ' + caughtException.getMessage()
        );

        // Nothing was invoiced, nothing was registered, nothing was committed
        System.assertEquals(1, gateway.authenticationCount, 'authenticate() must be attempted once');
        System.assertEquals(0, gateway.invoicedAccountIds.size(), 'No invoice may be created when authentication fails');

        ((IOpportunitiesSelector) mocks.verify(selectorMock, 0)).selectById(opportunityIds);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).commitWork();
    }

    @IsTest
    static void billingFailureMarksOpportunityAndContinuesWithTheRemainingOnes() {
        initMocks();

        Id failingAccountId = fflib_IDGenerator.generate(Account.SObjectType);
        Id goodAccountId = fflib_IDGenerator.generate(Account.SObjectType);

        Opportunity failing = opportunity(failingAccountId, CLOSED_WON, 75.00);
        Opportunity succeeding = opportunity(goodAccountId, CLOSED_WON, 125.00);

        Set<Id> opportunityIds = new Set<Id>{ failing.Id, succeeding.Id };

        mocks.when(selectorMock.selectById(opportunityIds))
            .thenReturn(new List<Opportunity>{ failing, succeeding });

        BillingGatewayStub gateway = new BillingGatewayStub()
            .withInvoiceFailure(failingAccountId, 'Invalid customer')
            .withInvoiceNumber(goodAccountId, 'INV-900');
        Application.Service.setMock(IBillingGateway.class, gateway);

        Integer invoiced;

        Test.startTest();
        invoiced = InvoicingService.invoiceWonOpportunities(opportunityIds);
        Test.stopTest();

        System.assertEquals(1, invoiced, 'Only the successfully invoiced opportunity counts');
        System.assertEquals(1, gateway.authenticationCount, 'authenticate() must be called once');

        System.assertEquals('Billing failed', failing.NextStep, 'The failing opportunity must be flagged');
        System.assertEquals('Invalid customer', failing.Description, 'The billing error must be stored');

        System.assertEquals('Invoiced: INV-900', succeeding.NextStep, 'The other opportunity must still be invoiced');
        System.assertEquals(null, succeeding.Description, 'The successful opportunity must not get an error description');

        System.assertEquals(
            new List<Id>{ failingAccountId, goodAccountId },
            gateway.invoicedAccountIds,
            'createInvoice must be called per opportunity in selector order'
        );
        System.assertEquals(
            new List<Decimal>{ failing.Amount, succeeding.Amount },
            gateway.invoicedAmounts,
            'createInvoice must receive the opportunity amount'
        );

        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).registerDirty(failing);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).registerDirty(succeeding);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).commitWork();
    }

    @IsTest
    static void noEligibleOpportunitiesCommitNothing() {
        initMocks();
        IBillingGateway gatewayMock = mockBillingGateway();

        Opportunity stillOpen = opportunity(fflib_IDGenerator.generate(Account.SObjectType), 'Prospecting', 1000.00);
        Set<Id> opportunityIds = new Set<Id>{ stillOpen.Id };

        mocks.when(selectorMock.selectById(opportunityIds))
            .thenReturn(new List<Opportunity>{ stillOpen });

        Integer invoiced;

        Test.startTest();
        invoiced = InvoicingService.invoiceWonOpportunities(opportunityIds);
        Test.stopTest();

        System.assertEquals(0, invoiced, 'Nothing qualifies, so nothing is invoiced');
        System.assertEquals(null, stillOpen.NextStep, 'The opportunity must not be touched');

        ((IBillingGateway) mocks.verify(gatewayMock, 1)).authenticate();
        ((IBillingGateway) mocks.verify(gatewayMock, 0)).createInvoice(stillOpen.AccountId, stillOpen.Amount);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).registerDirty(stillOpen);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).commitWork();
    }

    @IsTest
    static void emptyOrNullInputShortCircuits() {
        initMocks();
        IBillingGateway gatewayMock = mockBillingGateway();

        Integer invoicedForEmpty;
        Integer invoicedForNull;

        Test.startTest();
        invoicedForEmpty = InvoicingService.invoiceWonOpportunities(new Set<Id>());
        invoicedForNull = InvoicingService.invoiceWonOpportunities(null);
        Test.stopTest();

        System.assertEquals(0, invoicedForEmpty, 'An empty id set returns zero');
        System.assertEquals(0, invoicedForNull, 'A null id set returns zero');

        ((IBillingGateway) mocks.verify(gatewayMock, 0)).authenticate();
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).commitWork();
    }

    // ------------------------------------------------------------------ test double

    /**
     * Hand rolled, callout free billing gateway used where the double has to throw a
     * BillingException (ApexMocks can only stub methods that return a value).
     */
    private class BillingGatewayStub implements IBillingGateway {

