    /**
     * Sums, per StageName, Amount * Probability / 100 rounded to 2 decimals
     * per opportunity (the rounding must happen per opportunity, not on the
     * stage total).
     */
    static void sumsWeightedAmountsPerStageRoundingPerOpportunity() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector mockSelector =
            (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        Application.Selector.setMock(Opportunity.SObjectType, mockSelector);

        Id accountId1 = fflib_IDGenerator.generate(Account.SObjectType);
        Id accountId2 = fflib_IDGenerator.generate(Account.SObjectType);
        Set<Id> accountIds = new Set<Id>{ accountId1, accountId2 };

        List<Opportunity> opportunities = new List<Opportunity>{
            // 1.03 * 50 / 100 = 0.515 -> 0.52
            buildOpportunity(accountId1, 'Prospecting', 1.03, 50),
            // 1.03 * 50 / 100 = 0.515 -> 0.52
            buildOpportunity(accountId2, 'Prospecting', 1.03, 50),
            // 10.03 * 50 / 100 = 5.015 -> 5.02
            buildOpportunity(accountId1, 'Qualification', 10.03, 50)
        };

        mocks.startStubbing();
        mocks.when(mockSelector.selectOpenByAccountIds(accountIds)).thenReturn(opportunities);
        mocks.stopStubbing();

        Map<String, Decimal> result =
            OpportunityForecastService.weightedAmountByStage(accountIds);

        System.assertEquals(2, result.size(), 'Expected one total per stage');
        System.assertNotEquals(null, result.get('Prospecting'), 'Missing Prospecting total');
        System.assertNotEquals(null, result.get('Qualification'), 'Missing Qualification total');

        System.assertEquals(
            0,
            Decimal.valueOf('1.04').compareTo(result.get('Prospecting')),
            'Prospecting must be the sum of the per-opportunity rounded weights (0.52 + 0.52) and not a rounded stage total (1.03)'
        );
        System.assertEquals(
            0,
            Decimal.valueOf('5.02').compareTo(result.get('Qualification')),
            'Qualification must round 10.03 * 50 / 100 = 5.015 to 5.02'
        );

        ((IOpportunitiesSelector) mocks.verify(mockSelector, 1))
            .selectOpenByAccountIds(accountIds);
    }

