@IsTest
private class OpportunityCleanupServiceTest {

    private static final String STAGE_PROSPECTING = 'Prospecting';
    private static final String STAGE_QUALIFICATION = 'Qualification';
    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final String STAGE_CLOSED_LOST = 'Closed Lost';
    private static final Date CUTOFF = Date.newInstance(2024, 6, 1);

    // ---------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------

    private static Opportunity fakeOpportunity(String name, String stageName, Date closeDate) {
        return new Opportunity(
            Id = fflib_IDGenerator.generate(Opportunity.SObjectType),
            Name = name,
            StageName = stageName,
            CloseDate = closeDate
        );
    }

    private static Set<Id> idsOf(List<Opportunity> opportunities) {
        Set<Id> ids = new Set<Id>();
        for (Opportunity opportunity : opportunities) {
            ids.add(opportunity.Id);
        }
        return ids;
    }

    private static IOpportunitiesSelector mockSelector(fflib_ApexMocks mocks) {
        IOpportunitiesSelector selectorMock =
            (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        Application.Selector.setMock(Opportunity.SObjectType, selectorMock);
        return selectorMock;
    }

    private static fflib_ISObjectUnitOfWork mockUnitOfWork(fflib_ApexMocks mocks) {
        fflib_ISObjectUnitOfWork uowMock =
            (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);
        Application.UnitOfWork.setMock(uowMock);
        return uowMock;
    }

    private static void assertUntouched(Opportunity opportunity, String expectedStageName) {
        System.assertEquals(expectedStageName, opportunity.StageName,
            'StageName should not change for ' + opportunity.Name);
        System.assert(opportunity.Description == null,
            'Description should not change for ' + opportunity.Name);
    }

    // ---------------------------------------------------------------------
    // Tests
    // ---------------------------------------------------------------------

    @IsTest
    static void closesOnlyStaleOpportunities() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selectorMock = mockSelector(mocks);
        fflib_ISObjectUnitOfWork uowMock = mockUnitOfWork(mocks);

        Opportunity staleOne = fakeOpportunity('Stale One', STAGE_PROSPECTING, CUTOFF.addDays(-1));
        Opportunity staleTwo = fakeOpportunity('Stale Two', STAGE_QUALIFICATION, CUTOFF.addDays(-30));
        Opportunity onCutoff = fakeOpportunity('On Cutoff', STAGE_PROSPECTING, CUTOFF);
        Opportunity afterCutoff = fakeOpportunity('After Cutoff', STAGE_PROSPECTING, CUTOFF.addDays(1));
        Opportunity closedWon = fakeOpportunity('Won', STAGE_CLOSED_WON, CUTOFF.addDays(-5));
        Opportunity closedLost = fakeOpportunity('Lost', STAGE_CLOSED_LOST, CUTOFF.addDays(-5));
        Opportunity withoutCloseDate = fakeOpportunity('No Close Date', STAGE_PROSPECTING, null);

        List<Opportunity> selected = new List<Opportunity>{
            staleOne,
            staleTwo,
            onCutoff,
            afterCutoff,
            closedWon,
            closedLost,
            withoutCloseDate
        };
        Set<Id> ids = idsOf(selected);

        mocks.startStubbing();
        mocks.when(selectorMock.selectById(ids)).thenReturn(selected);
        mocks.stopStubbing();

        Integer closed = OpportunityCleanupService.closeStale(ids, CUTOFF);

        // Only the two opportunities strictly before the cutoff and not closed are counted.
        System.assertEquals(2, closed, 'Exactly the two stale opportunities should be closed');

        // Stale opportunities are closed with the standard lost reason.
        System.assertEquals(STAGE_CLOSED_LOST, staleOne.StageName, 'Stale opportunity should be closed lost');
        System.assertEquals(OpportunityCleanupService.LOST_REASON, staleOne.Description,
            'Stale opportunity should receive the lost reason');
        System.assertEquals(STAGE_CLOSED_LOST, staleTwo.StageName, 'Stale opportunity should be closed lost');
        System.assertEquals(OpportunityCleanupService.LOST_REASON, staleTwo.Description,
            'Stale opportunity should receive the lost reason');

        // Everything else is left untouched.
        assertUntouched(onCutoff, STAGE_PROSPECTING);
        assertUntouched(afterCutoff, STAGE_PROSPECTING);
        assertUntouched(closedWon, STAGE_CLOSED_WON);
        assertUntouched(closedLost, STAGE_CLOSED_LOST);
        assertUntouched(withoutCloseDate, STAGE_PROSPECTING);

        // The selector is queried exactly once with the supplied ids.
        ((IOpportunitiesSelector) mocks.verify(selectorMock, 1)).selectById(ids);

        // Only the stale opportunities are registered dirty.
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).registerDirty(staleOne);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).registerDirty(staleTwo);
        for (Opportunity untouched : new List<Opportunity>{
            onCutoff,
            afterCutoff,
            closedWon,
            closedLost,
            withoutCloseDate
        }) {
            ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).registerDirty(untouched);
        }

        // The unit of work is committed exactly once.
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).commitWork();
    }

    @IsTest
    static void returnsZeroAndDoesNotCommitWhenNothingIsStale() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();
