        Opportunity onCutoff = fakeOpportunity('On Cutoff', STAGE_PROSPECTING, CUTOFF);
        Opportunity afterCutoff = fakeOpportunity('After Cutoff', STAGE_PROSPECTING, CUTOFF.addDays(1));
        Opportunity closedWon = fakeOpportunity('Won', STAGE_CLOSED_WON, CUTOFF.addDays(-5));
        Opportunity closedLost = fakeOpportunity('Lost', STAGE_CLOSED_LOST, CUTOFF.addDays(-5));
        Opportunity withoutCloseDate = fakeOpportunity('No Close Date', STAGE_PROSPECTING, null);

        List<Opportunity> selected = new List<Opportunity>{
            onCutoff,
            afterCutoff,
            closedWon,
            closedLost,
            withoutCloseDate
        };
        Set<Id> ids = idsOf(selected);

        mocks.startStubbing();
        mocks.when(selectorMock.selectById(ids)).thenReturn(selected);
        mocks.stopStubbing();

        Integer closed = OpportunityCleanupService.closeStale(ids, CUTOFF);

        System.assertEquals(0, closed, 'Nothing is stale, so nothing is closed');

        assertUntouched(onCutoff, STAGE_PROSPECTING);
        assertUntouched(afterCutoff, STAGE_PROSPECTING);
        assertUntouched(closedWon, STAGE_CLOSED_WON);
        assertUntouched(closedLost, STAGE_CLOSED_LOST);
        assertUntouched(withoutCloseDate, STAGE_PROSPECTING);

        ((IOpportunitiesSelector) mocks.verify(selectorMock, 1)).selectById(ids);

        for (Opportunity untouched : selected) {
            ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).registerDirty(untouched);
        }

        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).commitWork();
    }

    @IsTest
    static void returnsZeroForNullIdsWithoutQueryingOrCommitting() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selectorMock = mockSelector(mocks);
        fflib_ISObjectUnitOfWork uowMock = mockUnitOfWork(mocks);

        Integer closed = OpportunityCleanupService.closeStale(null, CUTOFF);

