        return new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };
    }

    public override List<Schema.FieldSet> getSObjectFieldSetList() {
        return new List<Schema.FieldSet>{
            Schema.SObjectType.Account.fieldSets.Credit_Review
        };
    }

    public List<Account> selectById(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }
        return (List<Account>) selectSObjectsById(accountIds);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        fflib_QueryFactory queryFactory = newQueryFactory();
        queryFactory.subselectQuery('Contacts', new ContactsSelector());
        queryFactory.setConditionExpression('Id IN :accountIds');

        // The query factory is configured with DataAccess.USER_MODE by this
        // selector, so the generated SOQL carries WITH USER_MODE and the
        // platform enforces object, field and sharing access for the runner.
        return (List<Account>) Database.query(queryFactory.toSOQL());
    }
