`File: force-app/main/default/classes/ErpCustomerSync.cls`
```apex
/**
 * Sends new Accounts to the ERP:  POST callout:ERP/api/customers
 *
 * One HTTP request is sent per Account (as requested, so the ERP team can trace every
 * account on its own). Each request wraps exactly one customer in the JSON array the
 * API expects: [{"salesforceId": "001...", "name": "Acme GmbH", "country": "Germany"}]
 *
 * Why a Queueable instead of a callout inside AccountTrigger (the one deviation):
 *  - The insert that fired the trigger is uncommitted DML; a callout in that transaction
 *    throws "You have uncommitted work pending". Async Apex runs in its own transaction.
 *  - One transaction may make at most 100 callouts (and 120 s of callout time); a
 *    marketplace batch of 200 accounts would need 200 requests.
 *  - The trigger has a 10 s synchronous limit; ERP latency belongs in async context.
 *
 * Error handling and retries are out of scope for this ticket: failures are only logged.
 */
public with sharing class ErpCustomerSync implements Queueable, Database.AllowsCallouts {

    // Accounts (= callouts) per job. One callout per account, so jobs are kept small
    // and well below the 100-callout / 120 s limits and the queueable execution time.
    private static final Integer CALLS_PER_JOB = 50;

    // Maximum number of queueable jobs that can be enqueued in a single transaction.
    private static final Integer MAX_JOBS_PER_TRANSACTION = 50;

    private static final String ENDPOINT = 'callout:ERP/api/customers';
    private static final Integer TIMEOUT_MS = 30000;

    // Pre-built request bodies: keeps the serialized queueable state small.
    private final List<String> requestBodies;

    public ErpCustomerSync(List<String> requestBodies) {
        this.requestBodies = requestBodies;
    }

    /**
     * Splits the new accounts into chunks and enqueues one job per chunk.
     * Called from AccountTrigger (after insert). Works for a single account created by a
     * user (1 job, 1 callout) as well as a 200-record integration batch (4 jobs).
     */
    public static void enqueue(List<Account> newAccounts) {
        if (newAccounts == null || newAccounts.isEmpty()) {
            return;
        }

        List<String> bodies = new List<String>();
        for (Account acc : newAccounts) {
            bodies.add(buildBody(acc));
        }

        Integer jobs = 0;
        for (Integer start = 0; start < bodies.size(); start += CALLS_PER_JOB) {
            if (jobs == MAX_JOBS_PER_TRANSACTION) {
                System.debug(
                    LoggingLevel.ERROR,
                    'ErpCustomerSync: ' + (bodies.size() - start) + ' account(s) not sent to the ERP. '
                        + 'More than ' + (MAX_JOBS_PER_TRANSACTION * CALLS_PER_JOB)
                        + ' accounts in one transaction requires Batch Apex.'
                );
                break;
            }

            Integer stop = Math.min(start + CALLS_PER_JOB, bodies.size());
            List<String> chunk = new List<String>();
            for (Integer i = start; i < stop; i++) {
                chunk.add(bodies[i]);
            }

            System.enqueueJob(new ErpCustomerSync(chunk));
            jobs++;
        }
    }

    public void execute(QueueableContext context) {
        Http http = new Http();

        for (String body : requestBodies) {
            HttpRequest request = new HttpRequest();
            request.setEndpoint(ENDPOINT);
            request.setMethod('POST');
            request.setHeader('Content-Type', 'application/json');
            request.setTimeout(TIMEOUT_MS);
            request.setBody(body);

            try {
                HttpResponse response = http.send(request);
                if (response.getStatusCode() != 202) {
                    System.debug(
                        LoggingLevel.ERROR,
                        'ErpCustomerSync: ERP returned ' + response.getStatusCode()
                            + ' (' + response.getBody() + ') for payload ' + body
                    );
                }
            } catch (CalloutException e) {
                // Retries are out of scope: log and continue so the remaining accounts
                // of this job are still pushed.
                System.debug(LoggingLevel.ERROR, 'ErpCustomerSync: callout failed for ' + body + ': ' + e.getMessage());
            }
        }
    }

    /** Builds the ERP payload for one account: [{"salesforceId":"001..","name":"..","country":".."}] */
    private static String buildBody(Account acc) {
        String country = String.isBlank(acc.BillingCountry) ? null : acc.BillingCountry;

        Map<String, Object> customer = new Map<String, Object>();
        customer.put('salesforceId', String.valueOf(acc.Id)); // Ids in Apex are always the 18-character form
        customer.put('name', acc.Name);
        customer.put('country', country);

        return JSON.serialize(new List<Object>{ customer });
    }
}
