```apex
public with sharing class CaseSurveyJob implements Queueable, Database.Batchable<SObject> {
    /** Maximum number of Queueable jobs that can be enqueued from one transaction. */
    public static final Integer MAX_JOBS_PER_TRANSACTION = 50;

    private final Id caseId;
    private final List<Id> bulkCaseIds;

    /**
     * Per-case mode: enqueued from the trigger for normal bulk closes.
     */
    public CaseSurveyJob(Id caseId) {
        this.caseId = caseId;
        this.bulkCaseIds = new List<Id>();
    }

    /**
     * Bulk mode: executed as a batch with scope size 1 for large closes
     * (queueable enqueue limit exceeded).
     */
    public CaseSurveyJob(List<Id> caseIds) {
        this.caseId = null;
        this.bulkCaseIds = new List<Id>();
        if (caseIds != null) {
            for (Id id : caseIds) {
                if (id != null) {
                    this.bulkCaseIds.add(id);
                }
            }
        }
    }

    // ---------------------------------------------------------------------
    // Queueable (one case per job)
    // ---------------------------------------------------------------------
    public void execute(QueueableContext context) {
        if (caseId != null) {
            createSurveyTask(caseId);
        }
    }

    // ---------------------------------------------------------------------
    // Database.Batchable (overflow path, scope size 1 => one case per execute)
    // ---------------------------------------------------------------------
    public Database.QueryLocator start(Database.BatchableContext context) {
        return Database.getQueryLocator([
            SELECT Id
            FROM Case
            WHERE Id IN :bulkCaseIds
        ]);
    }

    public void execute(Database.BatchableContext context, List<Case> scope) {
        for (Case c : scope) {
            createSurveyTask(c.Id);
        }
    }

    public void finish(Database.BatchableContext context) {
        // Nothing to do.
    }

    // ---------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------
    private void createSurveyTask(Id surveyCaseId) {
        List<Case> cases = [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id = :surveyCaseId
              AND ContactId != null
            LIMIT 1
        ];

        if (cases.isEmpty()) {
            // Case deleted, or has no contact: no survey task.
            return;
        }

        Case c = cases[0];

        insert new Task(
            WhatId = c.Id,
            WhoId = c.ContactId,
            Subject = 'CSAT survey: ' + c.CaseNumber,
            ActivityDate = Date.today().addDays(2),
            Status = 'Not Started'
        );
    }
}
