import { LightningElement, api } from 'lwc';

const EMPTY = [];

/**
 * Presentational component: renders the contacts handed to it by the parent.
 * It never fetches data and never mutates the incoming array.
 */
export default class AccountContactList extends LightningElement {
    _contacts = EMPTY;

    /**
     * Array of { Id, Name, Title } supplied by the parent (Title is optional).
     * A setter is used so that every new array reference from the parent
     * triggers a re-render, and so that undefined/null/empty are normalised.
     */
    @api
    get contacts() {
        return this._contacts;
    }

    set contacts(value) {
        this._contacts = Array.isArray(value) ? value : EMPTY;
    }

    get hasContacts() {
        return this._contacts.length > 0;
    }

    get contactCountLabel() {
        const count = this._contacts.length;
        return count === 1 ? '1 contact' : `${count} contacts`;
    }

    /**
     * Sorted, render-ready view of the data. A copy is sorted so the parent's
     * array is left untouched.
     */
    get sortedContacts() {
        const rows = this._contacts.map((contact) => {
            const record = contact || {};
            const title = record.Title;
            return {
                key: record.Id,
                id: record.Id,
                name: record.Name,
                title,
                hasTitle: title !== undefined && title !== null && title !== ''
            };
        });

        rows.sort((a, b) => {
            const nameA = a.name === undefined || a.name === null ? '' : String(a.name);
            const nameB = b.name === undefined || b.name === null ? '' : String(b.name);
            return nameA.localeCompare(nameB);
        });

        return rows;
    }
}
