public with sharing class HouseholdService {
    private static final String HOUSEHOLD_RECORD_TYPE_DEVELOPER_NAME = 'HH_Account';

    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must contain at least one Contact');
        }

        Schema.RecordTypeInfo householdRecordType = Schema.SObjectType.Account
            .getRecordTypeInfosByDeveloperName()
            .get(HOUSEHOLD_RECORD_TYPE_DEVELOPER_NAME);

        if (householdRecordType == null || !householdRecordType.isActive()) {
            throw new System.TypeException(
                'Account record type with DeveloperName "HH_Account" is not available in this org.'
            );
        }

        Id householdRecordTypeId = householdRecordType.getRecordTypeId();
        Savepoint savepoint = Database.setSavepoint();

        try {
            // Let NPSP's Household Account triggers name the account and generate greetings.
            Account household = new Account(RecordTypeId = householdRecordTypeId);
            insert household;

            for (Contact member : members) {
                member.AccountId = household.Id;
            }
            insert members;

            // The first contact in the supplied list becomes the household's primary contact.
            Account primaryContactUpdate = new Account(
                Id = household.Id,
                RecordTypeId = householdRecordTypeId,
                npe01__One2OneContact__c = members[0].Id
            );
            update primaryContactUpdate;

            return household.Id;
        } catch (Exception ex) {
            Database.rollback(savepoint);
            throw ex;
        }
    }
}
