public class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    /**
     * Creates or updates NPSP partial soft credits for the supplied
     * opportunity/contact pairs.
     *
     * Each contact ends up with exactly one OpportunityContactRole on the
     * opportunity, and that role carries the requested role name. The partial
     * soft credit is linked to that contact role and carries the same role name.
     *
     * The whole call is validated before any DML is performed.
     */
    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> opportunityIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();

        for (SoftCreditRequest request : requests) {
            if (request == null || request.opportunityId == null || request.contactId == null) {
                throw new SoftCreditException(
                    'A soft credit request must include an opportunity and a contact.'
                );
            }
            opportunityIds.add(request.opportunityId);
            contactIds.add(request.contactId);
        }

        // Query 1: opportunities (amount and primary contact).
        Map<String, Opportunity> opportunitiesByKey = new Map<String, Opportunity>();
        for (Opportunity opportunity : [
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ]) {
            opportunitiesByKey.put(normalizeId(opportunity.Id), opportunity);
        }

        // Query 2: existing opportunity contact roles for the requested pairs.
        Map<String, List<OpportunityContactRole>> contactRolesByKey =
            new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole contactRole : [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :opportunityIds
              AND ContactId IN :contactIds
        ]) {
            String key = pairKey(contactRole.OpportunityId, contactRole.ContactId);
            List<OpportunityContactRole> roles = contactRolesByKey.get(key);
            if (roles == null) {
                roles = new List<OpportunityContactRole>();
                contactRolesByKey.put(key, roles);
            }
            roles.add(contactRole);
        }

        // Query 3: existing partial soft credits for the requested pairs.
        Map<String, npsp__Partial_Soft_Credit__c> softCreditsByKey =
            new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c softCredit : [
            SELECT Id,
                   npsp__Opportunity__c,
                   npsp__Contact__c,
                   npsp__Amount__c,
                   npsp__Role_Name__c,
                   npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :opportunityIds
              AND npsp__Contact__c IN :contactIds
        ]) {
            softCreditsByKey.put(
                pairKey(softCredit.npsp__Opportunity__c, softCredit.npsp__Contact__c),
                softCredit
            );
        }

        // Validate the entire call before any DML. If anything is invalid the
        // exception propagates and nothing has been changed.
        for (SoftCreditRequest request : requests) {
            Opportunity opportunity = opportunitiesByKey.get(normalizeId(request.opportunityId));
            if (opportunity == null) {
                throw new SoftCreditException('Opportunity not found: ' + request.opportunityId);
            }
            if (sameId(opportunity.npsp__Primary_Contact__c, request.contactId)) {
                throw new SoftCreditException(
                    'A contact cannot receive a soft credit on an opportunity where they are the primary contact.'
                );
            }
            if (request.amount == null) {
                throw new SoftCreditException('A soft credit amount is required.');
            }
            if (request.amount <= 0) {
                throw new SoftCreditException('A soft credit amount must be greater than zero.');
            }
            if (opportunity.Amount != null && request.amount > opportunity.Amount) {
                throw new SoftCreditException(
                    'A soft credit amount cannot be greater than the opportunity amount.'
                );
            }
        }

        // Make sure each pair has exactly one contact role, carrying the requested role.
        List<OpportunityContactRole> contactRoleUpserts = new List<OpportunityContactRole>();
        List<OpportunityContactRole> contactRoleDeletes = new List<OpportunityContactRole>();
        Map<String, OpportunityContactRole> contactRoleByKey =
            new Map<String, OpportunityContactRole>();

        for (SoftCreditRequest request : requests) {
            String key = pairKey(request.opportunityId, request.contactId);
            List<OpportunityContactRole> existingRoles = contactRolesByKey.get(key);

            OpportunityContactRole contactRole;
            if (existingRoles != null && !existingRoles.isEmpty()) {
                // Reuse the existing contact role (for example the Household Member
                // role NPSP creates) and remove any additional roles for this pair.
                contactRole = existingRoles[0];
                for (Integer i = 1; i < existingRoles.size(); i++) {
                    contactRoleDeletes.add(existingRoles[i]);
                }
                contactRole.Role = request.role;
            } else {
                contactRole = new OpportunityContactRole(
                    OpportunityId = request.opportunityId,
                    ContactId = request.contactId,
                    Role = request.role
                );
            }
            contactRoleUpserts.add(contactRole);
            contactRoleByKey.put(key, contactRole);
        }

        // DML 1: insert new contact roles / update the existing ones.
        if (!contactRoleUpserts.isEmpty()) {
            upsert contactRoleUpserts;
        }

        // Build the partial soft credits, linked to the contact role for each pair.
        List<npsp__Partial_Soft_Credit__c> softCreditUpserts =
            new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest request : requests) {
            String key = pairKey(request.opportunityId, request.contactId);
            npsp__Partial_Soft_Credit__c softCredit = softCreditsByKey.get(key);
            if (softCredit == null) {
                softCredit = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = request.opportunityId,
                    npsp__Contact__c = request.contactId
                );
                softCreditsByKey.put(key, softCredit);
            }
            softCredit.npsp__Amount__c = request.amount;
            softCredit.npsp__Role_Name__c = request.role;
            softCredit.npsp__Contact_Role_ID__c =
                String.valueOf(contactRoleByKey.get(key).Id);
            softCreditUpserts.add(softCredit);
        }

        // DML 2: insert new partial soft credits / update the existing ones.
        if (!softCreditUpserts.isEmpty()) {
            upsert softCreditUpserts;
        }

        // DML 3 (only when a pair somehow had more than one contact role).
        if (!contactRoleDeletes.isEmpty()) {
            delete contactRoleDeletes;
        }
    }

    /**
     * Builds a map key for an opportunity/contact pair. Ids are normalized to
     * their 15-character representation so that 15- and 18-character Ids for
     * the same record always produce the same key.
     */
    private static String pairKey(Id opportunityId, Id contactId) {
        return normalizeId(opportunityId) + '|' + normalizeId(contactId);
    }

    private static String normalizeId(Id value) {
        if (value == null) {
            return '';
        }
        String idString = String.valueOf(value);
        if (idString.length() > 15) {
            idString = idString.substring(0, 15);
        }
        return idString;
    }

    private static Boolean sameId(Id first, Id second) {
        String firstKey = normalizeId(first);
        return firstKey != '' && firstKey == normalizeId(second);
    }
}
