/**
 * TDTM trigger handler for creating major gift follow-up Tasks on Opportunities.
 *
 * Registered in NPSP under Trigger Configuration as:
 *   Class: OPP_MajorGiftFollowUp_TDTM, Object: Opportunity,
 *   Trigger Action: AfterInsert;AfterUpdate, Load Order: 5, Asynchronous: false
 *
 * Creates exactly one Task when an Opportunity becomes Closed Won with
 * Amount >= 5000 (on insert, or on update where it was not already qualified).
 * Bulk-safe: one SOQL-free pass and a single DML statement for up to 200 records.
 */
public with sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final String CLOSED_WON = 'Closed Won';
    private static final Decimal MAJOR_GIFT_AMOUNT = 5000;

    public override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();

        if (newlist == null || newlist.isEmpty()) {
            return dmlWrapper;
        }

        // Only react to AfterInsert / AfterUpdate.
        if (triggerAction != npsp.TDTM_Runnable.Action.AfterInsert
            && triggerAction != npsp.TDTM_Runnable.Action.AfterUpdate) {
            return dmlWrapper;
        }

        List<Task> tasksToInsert = new List<Task>();

        for (Integer i = 0; i < newlist.size(); i++) {
            SObject newRec = newlist[i];
            if (!(newRec instanceof Opportunity)) {
                continue;
            }

            Opportunity opp = (Opportunity) newRec;

            // Skip anything not currently a qualifying major gift.
            if (!isQualifiedMajorGift(opp)) {
                continue;
            }

            // On update, only act when the record newly qualifies.
            if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate) {
                Boolean wasQualified = false;
                if (oldlist != null
                    && i < oldlist.size()
                    && oldlist[i] instanceof Opportunity) {
                    wasQualified = isQualifiedMajorGift((Opportunity) oldlist[i]);
                }
                if (wasQualified) {
                    continue;
                }
            }

            tasksToInsert.add(buildFollowUpTask(opp));
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }

        return dmlWrapper;
    }

    private static Boolean isQualifiedMajorGift(Opportunity opp) {
        return opp != null
            && opp.StageName == CLOSED_WON
            && opp.Amount != null
            && opp.Amount >= MAJOR_GIFT_AMOUNT;
    }

    private static Task buildFollowUpTask(Opportunity opp) {
        Task t = new Task();
        t.Subject = 'Major gift thank-you call';
        t.Priority = 'High';
        t.Status = 'Not Started';
        t.WhatId = opp.Id;
        t.WhoId = opp.npsp__Primary_Contact__c;
        t.OwnerId = opp.OwnerId;

        if (opp.CloseDate != null) {
            t.ActivityDate = opp.CloseDate.addDays(3);
        }

        return t;
    }
}
