File: force-app/main/default/classes/RecordAccessService.cls
```apex
public with sharing class RecordAccessService {
    // Keep each IN-list small enough that Salesforce does not internally split the
    // query (which can surface as "Variable does not exist: tmpVarN") and so the
    // number of SOQL statements stays well under the 20-query budget.
    private static final Integer CHUNK_SIZE = 200;

    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editable = new Set<Id>();

        if (recordIds == null || recordIds.isEmpty()) {
            return editable;
        }

        // Normalize and drop nulls.
        Set<Id> idsToCheck = new Set<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null) {
                idsToCheck.add(recordId);
            }
        }

        if (idsToCheck.isEmpty()) {
            return editable;
        }

        // Chunk the IDs so each query binds a manageable collection.
        // UserRecordAccess.RecordId is polymorphic, so mixed object types are fine.
        List<Id> idList = new List<Id>(idsToCheck);
        Integer total = idList.size();

        for (Integer start = 0; start < total; start += CHUNK_SIZE) {
            Integer stop = Math.min(start + CHUNK_SIZE, total);
            Set<Id> chunk = new Set<Id>();
            for (Integer i = start; i < stop; i++) {
                chunk.add(idList[i]);
            }

            for (UserRecordAccess access : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :UserInfo.getUserId()
                  AND RecordId IN :chunk
            ]) {
                if (access.HasEditAccess == true) {
                    editable.add(access.RecordId);
                }
            }
        }

        return editable;
    }
}
